// Some portions generated by Co-Pilot
"use client";

import { useEffect, useState } from "react";
import { useTranslations } from "next-intl";
import { useSearchParams } from "next/navigation";
import { FiRefreshCw } from "react-icons/fi";
import { loadLatestAssets } from "@/hooks";
import type { TemurinAssets, OS, Arch } from "@/types/temurin";
import { setURLParam } from "@/utils/setURLParam";
import ReleaseFilters from "@/components/Temurin/Releases/ReleaseFilters";
import ReleaseResults from "@/components/Temurin/Releases/ReleaseResults";
import ReleaseLinks from "@/components/Temurin/Releases/ReleaseLinks";
import OneClickDownload from "@/components/Temurin/Releases/OneClickDownload";
import DownloadMethods from "@/components/Temurin/DownloadMethods";
import VersionSelector from "@/components/VersionSelector";
import ChecksumModal from "@/components/Download/ChecksumModal";

interface AvailableReleases {
  available_lts_releases: number[];
  available_releases: number[];
  most_recent_lts: number;
}

interface ReleaseRequest {
  key: string;
  assets: TemurinAssets;
  failed: boolean;
}

const operatingSystems: OS[] = [
  "any",
  "linux",
  "windows",
  "mac",
  "solaris",
  "aix",
  "alpine-linux",
];
const architectures: Arch[] = [
  "any",
  "x64",
  "x86",
  "x32",
  "ppc64",
  "ppc64le",
  "s390x",
  "aarch64",
  "arm",
  "sparcv9",
  "riscv64",
];

export default function TemurinReleasesPage({
  availableReleases,
}: {
  availableReleases: AvailableReleases;
}) {
  const t = useTranslations("TemurinReleases");
  const searchParams = useSearchParams();
  const params = Object.fromEntries(searchParams.entries());
  const latestLTS = availableReleases.most_recent_lts;
  const requestedVersion = Number(params.version);
  const validVersion =
    availableReleases.available_releases.includes(requestedVersion);
  const selectedVersion = validVersion
    ? String(requestedVersion)
    : String(latestLTS);
  const selectedOS = operatingSystems.find((os) => os === params.os) ?? "any";
  const selectedArch =
    architectures.find((arch) => arch === params.arch) ?? "any";
  const invalidFilters = Boolean(
    (params.version &&
      !validVersion &&
      params.version !== "latest" &&
      params.version !== "any") ||
    (params.os && !operatingSystems.some((os) => os === params.os)) ||
    (params.arch && !architectures.some((arch) => arch === params.arch)),
  );
  const isAllVersionsMode =
    params.mode === "filter" ||
    !availableReleases.available_lts_releases.includes(
      Number(selectedVersion),
    ) ||
    selectedOS !== "any" ||
    selectedArch !== "any";
  const ltsVersions = [...availableReleases.available_lts_releases]
    .sort((a, b) => b - a)
    .map((version) => ({ name: `${version} - LTS`, value: version }));
  const allVersions = [...availableReleases.available_releases]
    .sort((a, b) => b - a)
    .map((version) => ({
      name: availableReleases.available_lts_releases.includes(version)
        ? `${version} - LTS`
        : String(version),
      value: String(version),
    }));

  const [retry, setRetry] = useState(0);
  const requestKey = `${selectedVersion}:${selectedOS}:${selectedArch}:${retry}`;
  const [result, setResult] = useState<ReleaseRequest>({
    key: "",
    assets: [],
    failed: false,
  });
  const [currentChecksum, setCurrentChecksum] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const isLoading = result.key !== requestKey;
  const releases = isLoading ? [] : result.assets;
  const failed = !isLoading && result.failed;

  useEffect(() => {
    let active = true;
    loadLatestAssets(Number(selectedVersion), selectedOS, selectedArch)
      .then((assets) => {
        if (active) setResult({ key: requestKey, assets, failed: false });
      })
      .catch((error) => {
        if (!active) return;
        console.error("Error fetching releases:", error);
        setResult({ key: requestKey, assets: [], failed: true });
      });
    return () => {
      active = false;
    };
  }, [requestKey, selectedVersion, selectedOS, selectedArch]);

  const updateFilters = (
    version: string,
    os: string,
    arch: string,
    filterMode: boolean,
  ) => {
    setURLParam("version", version);
    setURLParam("os", os);
    setURLParam("arch", arch);
    setURLParam("mode", filterMode ? "filter" : undefined);
  };

  return (
    <div className="bg-purple text-white">
      <header className="border-b border-white/10 bg-[radial-gradient(ellipse_at_top_right,#7026b926,transparent_65%)]">
        <div className="mx-auto max-w-7xl px-6 py-8 sm:px-8 sm:py-7">
          <p className="mb-3 font-mono text-xs tracking-[0.2em] text-[#ff91b7]">
            ECLIPSE TEMURIN
          </p>
          <h1 className="mb-3 text-3xl font-semibold leading-tight tracking-tight sm:text-5xl">
            {t("title")}
          </h1>
          <p className="mb-0 max-w-2xl text-sm leading-relaxed text-grey sm:text-base">
            {t("description")}
          </p>
        </div>
      </header>

      <div className="mx-auto max-w-7xl px-6 pb-12 pt-6 sm:px-8 sm:pb-16">
        <div className="rounded-2xl border border-white/10 bg-white/[0.025] p-4">
          <VersionSelector
            activeVersionTab={isAllVersionsMode ? 1 : Number(selectedVersion)}
            setActiveVersionTab={(tab) =>
              updateFilters(
                tab === 1 ? selectedVersion : String(tab),
                "any",
                "any",
                tab === 1,
              )
            }
            versions={ltsVersions}
          />
          {isAllVersionsMode && (
            <ReleaseFilters
              onFiltersChange={(version, os, arch) =>
                updateFilters(version, os, arch, true)
              }
              version={selectedVersion}
              os={selectedOS}
              arch={selectedArch}
              allVersions={allVersions}
              latestLTS={latestLTS}
            />
          )}
        </div>
        {invalidFilters && (
          <p role="status" className="mb-0 mt-4 text-sm text-[#ffb7d0]">
            {t("invalid-filters")}
          </p>
        )}

        {!isAllVersionsMode && !failed && (
          <section aria-label={t("quick-downloads")} className="mt-6">
            <h2 className="sr-only">{t("quick-downloads")}</h2>
            <OneClickDownload
              selectedVersion={selectedVersion}
              releases={releases}
            />
          </section>
        )}

        <ReleaseLinks selectedVersion={selectedVersion} releases={releases} />

        <div className="mb-4 mt-8 flex flex-wrap items-center justify-between gap-3">
          <h2 className="mb-0 text-xl font-semibold tracking-tight">
            {t("all-builds")}
          </h2>
          <span className="rounded-full border border-white/10 px-3 py-1 font-mono text-xs text-grey">
            {`JDK ${selectedVersion}${availableReleases.available_lts_releases.includes(Number(selectedVersion)) ? " LTS" : ""}`}
          </span>
        </div>
        {failed ? (
          <div
            role="alert"
            className="rounded-2xl border border-pink/30 bg-pink/5 p-6"
          >
            <p className="mb-4 text-sm text-grey">{t("load-error")}</p>
            <button
              type="button"
              onClick={() => setRetry((value) => value + 1)}
              className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-pink px-4 py-2 text-sm font-semibold text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-white"
            >
              <FiRefreshCw aria-hidden="true" />
              <span>{t("retry")}</span>
            </button>
          </div>
        ) : (
          <ReleaseResults
            releases={releases}
            isLoading={isLoading}
            openModalWithChecksum={(checksum) => {
              setCurrentChecksum(checksum);
              setModalOpen(true);
            }}
          />
        )}
      </div>
      <DownloadMethods />
      <ChecksumModal
        open={modalOpen}
        setOpen={setModalOpen}
        checksum={currentChecksum}
      />
    </div>
  );
}
